#include "power_weight_registry_host.h"
#include <windows.h>
#include <algorithm>
#include <regex>
namespace druta::ui {
namespace {
[[noreturn]]void fail(const char* message,VoltagePolicyAvailability kind){throw VoltageEquationEvidenceError(message,kind);}
std::wstring lower(std::wstring s){for(auto& c:s)if(c>=L'A'&&c<=L'Z')c=static_cast<wchar_t>(c+L'a'-L'A');return s;}
bool managed(const std::wstring& name){const auto s=lower(name);if(s==L"vbios"||s==L"enablegpufirmware")return true;if(s.size()!=13||s.substr(0,11)!=L"romoverride")return false;for(size_t i=11;i<13;++i)if(!((s[i]>=L'0'&&s[i]<=L'9')||(s[i]>=L'a'&&s[i]<=L'f')))return false;return true;}
PowerWeightRegistrySnapshot native_read(const std::wstring& key){HKEY handle=nullptr;const auto opened=RegOpenKeyExW(HKEY_LOCAL_MACHINE,key.c_str(),0,KEY_READ|KEY_WOW64_64KEY,&handle);if(opened!=ERROR_SUCCESS)fail("Display driver registry key unavailable",opened==ERROR_FILE_NOT_FOUND||opened==ERROR_PATH_NOT_FOUND?VoltagePolicyAvailability::unsupported:VoltagePolicyAvailability::transient);
 struct Close{HKEY h;~Close(){RegCloseKey(h);}} close{handle};DWORD count=0,max_name=0,max_data=0;auto status=RegQueryInfoKeyW(handle,nullptr,nullptr,nullptr,nullptr,nullptr,nullptr,&count,&max_name,&max_data,nullptr,nullptr);if(status!=ERROR_SUCCESS)fail("Registry inventory unavailable",VoltagePolicyAvailability::transient);if(count>4096||max_name>16383)fail("Registry inventory exceeds bounds",VoltagePolicyAvailability::invalid);
 PowerWeightRegistrySnapshot out;std::vector<wchar_t> name(size_t(max_name)+2);for(DWORD i=0;i<count;++i){DWORD n=static_cast<DWORD>(name.size()),size=0,type=0;status=RegEnumValueW(handle,i,name.data(),&n,nullptr,&type,nullptr,&size);if(status!=ERROR_SUCCESS)fail("Registry inventory changed during read",VoltagePolicyAvailability::transient);std::wstring value(name.data(),n);if(!managed(value))continue;if(size>0x100000)fail("Managed registry value exceeds bounds",VoltagePolicyAvailability::invalid);std::vector<uint8_t> data(size);DWORD actual=size,read_type=0;const auto read=RegQueryValueExW(handle,value.c_str(),nullptr,&read_type,data.empty()?nullptr:data.data(),&actual);if(read!=ERROR_SUCCESS||actual!=size||read_type!=type)fail("Managed registry value changed during read",VoltagePolicyAvailability::transient);out.push_back({std::move(value),type,std::move(data)});}return out;}
PowerWeightRegistrySnapshot normalize(PowerWeightRegistrySnapshot s){for(const auto& v:s)if(!managed(v.name)||v.bytes.size()>0x100000||v.name.find(L'\0')!=std::wstring::npos)fail("Managed registry value malformed",VoltagePolicyAvailability::invalid);if(s.size()>258)fail("Managed registry inventory exceeds bounds",VoltagePolicyAvailability::invalid);std::sort(s.begin(),s.end(),[](const auto& a,const auto& b){return lower(a.name)<lower(b.name);});for(size_t i=1;i<s.size();++i)if(lower(s[i-1].name)==lower(s[i].name))fail("Registry case alias conflict",VoltagePolicyAvailability::invalid);return s;}
}
PowerWeightRegistrySnapshot read_power_weight_registry(const VoltageScaffoldWindowsTarget& target,const PowerWeightRegistryReader& reader){static const std::regex key(R"(^SYSTEM\\CurrentControlSet\\Control\\Class\\\{4d36e968-e325-11ce-bfc1-08002be10318\}\\[0-9]{4}$)",std::regex::icase);static const std::regex instance(R"(^PCI\\VEN_10DE&DEV_[0-9A-F]{4}&SUBSYS_[0-9A-F]{8}(&[A-Z0-9_]+)*\\[^\\]+$)",std::regex::icase);
 static const std::regex slot(R"(^[0-9a-f]{4}:[0-9a-f]{2}:[0-9a-f]{2}\.[0-7]$)",std::regex::icase);
 if(!std::regex_match(target.slot,slot)||target.slot.find('\0')!=std::string::npos||target.driver_key.size()>512||target.instance_id.size()>32768||!std::regex_match(target.driver_key,key)||!std::regex_match(target.instance_id,instance))fail("Malformed resolved display registry target",VoltagePolicyAvailability::invalid);const std::wstring path(target.driver_key.begin(),target.driver_key.end());auto one=normalize(reader?reader(path):native_read(path));auto two=normalize(reader?reader(path):native_read(path));if(one.size()!=two.size())fail("Managed registry inventory changed",VoltagePolicyAvailability::transient);for(size_t i=0;i<one.size();++i)if(lower(one[i].name)!=lower(two[i].name)||one[i].type!=two[i].type||one[i].bytes!=two[i].bytes)fail("Managed registry values changed",VoltagePolicyAvailability::transient);return two;}
}
